class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.used = set()
        self.evict = set()

    def get(self, key):
        if key in self.cache:
            if key in self.used:
                self.evict()
            return self.cache[key]
        return -1

    def put(self, key, value):
        if key in self.cache:
            if key in self.used:
                self.evict()
            self.cache[key] = value
            self.used.add(key)
        else:
            self.cache[key] = value
            self.used.add(key)
            if len(self.cache) > self.capacity:
                del self.cache[max(key, self.cache[max(key)].key)]
                self.evict()

    def evict(self):
        if len(self.cache) > self.capacity:
            key = max(self.cache.keys(), key=self.cache[max(self.cache.keys(), key).__hash__()).key)
            del self.cache[key]
            self.evict()

        return -1

